package com.mukasanches.zapptv

import android.content.Intent
import android.os.Bundle
import android.view.KeyEvent
import android.view.WindowManager
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import com.mukasanches.zapptv.platform.CatalogRefreshWorker
import com.mukasanches.zapptv.ui.SanchesTvApp

class MainActivity : ComponentActivity() {
    private var tvKeyHandler: ((KeyEvent) -> Boolean)? = null
    private var deepLinkChannelId by mutableStateOf<String?>(null)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        deepLinkChannelId = channelIdFrom(intent)
        CatalogRefreshWorker.schedule(applicationContext)
        window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)

        setContent {
            SanchesTvApp(
                initialChannelId = deepLinkChannelId,
                registerKeyHandler = { handler ->
                    tvKeyHandler = handler
                }
            )
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        deepLinkChannelId = channelIdFrom(intent)
    }

    override fun dispatchKeyEvent(event: KeyEvent): Boolean {
        if (tvKeyHandler?.invoke(event) == true) return true
        return super.dispatchKeyEvent(event)
    }

    override fun onDestroy() {
        tvKeyHandler = null
        super.onDestroy()
    }

    private fun channelIdFrom(intent: Intent?): String? {
        val uri = intent?.data ?: return null
        if (!uri.scheme.equals("sanchestv", ignoreCase = true)) return null
        if (!uri.host.equals("channel", ignoreCase = true)) return null
        return uri.pathSegments.firstOrNull()?.takeIf(String::isNotBlank)
    }
}

